// Reuse the existing mode, camera and control nodes. No parallel simulation state.
export class Experience147{
 constructor(doc=document,win=window){this.doc=doc;this.win=win;const $=id=>doc.getElementById(id);if(!$('home114')||!$('sim106-shell')||$('ui147-activity-dialog'))return;doc.body.dataset.design147='true';
  const title=$('game-home-title');title.innerHTML='METRO<span>CDMX</span>';const intro=doc.querySelector('.home114-intro');if(intro)intro.innerHTML='Una ciudad. Dos líneas. Tu próximo desafío.<br>Explora la flota, entra a cabina o aprende en el taller.';
  const label=doc.querySelector('.home114-mode-heading')?.querySelector('span');if(label)label.textContent='ELIGE UNA ACTIVIDAD';
  const dialog=doc.createElement('dialog');dialog.id='ui147-activity-dialog';dialog.setAttribute('aria-labelledby','ui147-activity-title');dialog.innerHTML='<div class="ui147-dialog-head"><div><small>METROLAB / ACTIVIDADES</small><h2 id="ui147-activity-title">¿Qué quieres hacer?</h2></div><button data-ui147-close="" aria-label="Cerrar actividades">×</button></div><nav aria-label="Cambiar actividad"></nav><p>El cambio prepara los recursos de la actividad seleccionada.</p>';doc.body.append(dialog);
  const modes={explore:['Explorar trenes','Modelos, piezas y cabinas'],operator:['Conducir','Tracción, frenado y puertas'],automatic:['Seguir trenes','Recorridos, cámaras y mapa'],maintenance:['Taller de trenes','Cuatro misiones con herramientas'],substations:['Subestaciones','Explorar equipos y realizar prácticas']};for(const[id,[name,detail]]of Object.entries(modes)){const b=doc.createElement('button');b.setAttribute('type','button');b.dataset.mode147=id;b.innerHTML='<b>'+name+'</b><span>'+detail+'</span><i aria-hidden="true">→</i>';b.addEventListener('click',()=>{dialog.close();win.metroGame?.choose(id);});dialog.querySelector('nav').append(b);}dialog.querySelector('[data-ui147-close]').onclick=()=>dialog.close();
  this.launcher=doc.createElement('button');this.launcher.id='ui147-change';this.launcher.textContent='Actividades';this.launcher.onclick=()=>dialog.showModal();$('g105-context').querySelector('.g105-context-actions').prepend(this.launcher);
  const strip=doc.createElement('nav');strip.id='ui147-camera-strip';strip.setAttribute('aria-label','Cámaras y navegación');const cameraGroup=doc.createElement('div');cameraGroup.className='ui147-camera-buttons';strip.append(cameraGroup);for(const id of['camera-full','camera-platform','camera-train','camera-driver','camera-cab-platform','camera-car','camera-passenger'])cameraGroup.append($(id));
  const right=doc.createElement('div');right.className='ui147-view-actions';strip.append(right);const navigate=$('sim106-cameras');right.append(navigate,$('sim106-map'));navigate.innerHTML='Navegar <kbd>C</kbd>';$('sim106-camera-panel').querySelector('.sim106-popover-head').querySelector('b').textContent='Mover la cámara';$('sim106-shell').insertBefore(strip,$('sim106-stage'));
  // Show the native line / convoy picker directly in the session header.
  const selection=doc.createElement('div');selection.id='ui147-selection';selection.append($('sim106-lines'),$('sim106-train-picker'));$('sim106-shell').querySelector('.sim106-bar').insertBefore(selection,$('sim106-shell').querySelector('.sim106-bar-actions'));
  this.render=()=>{const simulation=doc.body.dataset.gameScreen==='simulation';const host=simulation?$('sim106-shell').querySelector('.sim106-bar-actions'):$('g105-context').querySelector('.g105-context-actions');if(this.launcher.parentElement!==host)host.prepend(this.launcher);const driving=simulation&&doc.body.dataset.driving==='true';$('scene-train').disabled=driving;for(const id of ['line1','line8'])$(id).disabled=driving;$('scene-train').title=driving?'Tren bajo control. Cambia de modelo desde Actividades y Explorar trenes.':'Selecciona el convoy que deseas seguir';const mode=doc.body.dataset.gameScreen==='maintenance'?'maintenance':simulation?doc.body.dataset.driving==='true'?'operator':'automatic':'explore';for(const b of dialog.querySelectorAll('[data-mode147]'))b.setAttribute('aria-current',String(b.dataset.mode147===mode));};
  this.observer=new MutationObserver(this.render);this.observer.observe(doc.body,{attributes:true,attributeFilter:['data-game-screen','data-driving']});this.render();win.dispatchEvent(new Event('resize'));
 }
}
if(typeof document!=='undefined'){const mount=()=>{if(document.getElementById('home114')&&document.getElementById('sim106-shell')&&!document.getElementById('ui147-activity-dialog'))window.metroUI147=new Experience147();};mount();if(!document.getElementById('ui147-activity-dialog')){const obs=new MutationObserver(()=>{mount();if(document.getElementById('ui147-activity-dialog'))obs.disconnect();});obs.observe(document.body,{childList:true,subtree:true});}}
